using System.Collections.Immutable;using System.Data;using System.Text.Json;using Microsoft.Extensions.Options;using Npgsql;using NpgsqlTypes;using Platform.SoftwareFactory.Delivery;using Platform.SoftwareFactory.InternalService;
namespace Platform.SoftwareFactory.Persistence;
public sealed class PostgreSqlAuthorizedGitReceiptReader(NpgsqlDataSource data,IOptions<PostgreSqlIntentRegistrationOptions> cfg):IAuthorizedGitSourceCommitReceiptReader{public async Task<GovernedGitSourceCommitReceipt?> LoadAsync(Guid id,string tenant,CancellationToken ct){var o=cfg.Value;if(!o.IsOperationallyConfigured)throw new CiCdDependencyUnavailableException("Git evidence not configured.");const string sql="SELECT record_json,record_sha256_digest,evidence_reference,evidence_references,recorded_at FROM software_factory.git_evidence WHERE tenant_id=@tenant AND operation_id=@id";try{await using var cn=await data.OpenConnectionAsync(ct);await using var cmd=new NpgsqlCommand(sql,cn){CommandTimeout=o.CommandTimeoutSeconds};TestsDb.Add(cmd,"tenant",NpgsqlDbType.Text,tenant);TestsDb.Add(cmd,"id",NpgsqlDbType.Uuid,id);await using var r=await cmd.ExecuteReaderAsync(CommandBehavior.SingleRow,ct);if(!await r.ReadAsync(ct))return null;var x=JsonSerializer.Deserialize<GitEvidenceRecord>(r.GetString(0))??throw new InvalidOperationException();if(!StringComparer.OrdinalIgnoreCase.Equals(r.GetString(1),TestsDb.Digest(x))||!x.Commit.CommitSigned||!x.Commit.SourceMutationOccurred||x.Commit.CiCdTriggered||x.Commit.ProductionEffectOccurred)throw new InvalidOperationException("Git evidence binding invalid.");var refs=x.EvidenceReferences.Concat(r.GetFieldValue<string[]>(3)).Append(r.GetString(2)).Distinct(StringComparer.Ordinal).ToImmutableArray();return new(id,x.ReviewId,x.TestsExecutionId,x.GenerationId,x.DeliveryRunId,tenant,GovernedIntentPolicyOutcome.Permit,true,true,false,false,false,x.ChangeSet.CandidateSha256Digest,x.ReviewPackageSha256Digest,x.ChangeSet.ChangeSetSha256Digest,x.Commit.RepositoryId,x.Commit.ChangeBranch,x.Commit.BaseCommitId,x.Commit.CommitId,x.Commit.TreeSha256Digest,true,x.Commit.AppliedChanges.Select(c=>new GovernedGitAppliedChangeProof(c.RelativePath,c.Operation,c.ExpectedPreviousSha256Digest,c.NewContentSha256Digest)).ToImmutableArray(),r.GetString(2),refs,"Separately approved CI/CD",new(r.GetDateTime(4).ToUniversalTime()));}catch(NpgsqlException){throw new CiCdDependencyUnavailableException("Git evidence unavailable.");}}}
public sealed class PostgreSqlCiCdRunReader(NpgsqlDataSource data,IOptions<PostgreSqlIntentRegistrationOptions> cfg):ICiCdDeliveryRunReader{public async Task<SoftwareDeliveryRun?> LoadAsync(Guid id,string tenant,CancellationToken ct){var o=cfg.Value;if(!o.IsOperationallyConfigured)throw new CiCdDependencyUnavailableException("CI/CD run not configured.");const string sql="SELECT record_json,record_sha256_digest,evidence_reference FROM software_factory.cicd_delivery_run_snapshots WHERE tenant_id=@tenant AND run_id=@id";try{await using var cn=await data.OpenConnectionAsync(ct);await using var cmd=new NpgsqlCommand(sql,cn){CommandTimeout=o.CommandTimeoutSeconds};TestsDb.Add(cmd,"tenant",NpgsqlDbType.Text,tenant);TestsDb.Add(cmd,"id",NpgsqlDbType.Uuid,id);await using var r=await cmd.ExecuteReaderAsync(CommandBehavior.SingleRow,ct);if(!await r.ReadAsync(ct))return null;var run=JsonSerializer.Deserialize<SoftwareDeliveryRun>(r.GetString(0))??throw new InvalidOperationException();run.Validate();var d=TestsDb.Digest(run);if(run.CurrentStage!=DeliveryStage.Git||!StringComparer.OrdinalIgnoreCase.Equals(r.GetString(1),d)||r.GetString(2)!=$"evidence://delivery-runs/{id:D}/sha256/{d}")throw new InvalidOperationException("CI/CD run binding invalid.");return run;}catch(NpgsqlException){throw new CiCdDependencyUnavailableException("CI/CD run unavailable.");}}}
public sealed class PostgreSqlCiCdWorkflowReader(NpgsqlDataSource data,IOptions<PostgreSqlIntentRegistrationOptions> cfg):IGovernedCiCdWorkflowDefinitionReader{public async Task<GovernedCiCdWorkflowDefinition?> LoadAsync(string id,string version,string tenant,CancellationToken ct){var o=cfg.Value;if(!o.IsOperationallyConfigured)throw new CiCdDependencyUnavailableException("Workflow catalog not configured.");const string sql="SELECT record_json,record_sha256_digest FROM software_factory.cicd_workflow_definitions WHERE tenant_id=@tenant AND workflow_definition_id=@id AND version=@version";try{await using var cn=await data.OpenConnectionAsync(ct);await using var cmd=new NpgsqlCommand(sql,cn){CommandTimeout=o.CommandTimeoutSeconds};TestsDb.Add(cmd,"tenant",NpgsqlDbType.Text,tenant);TestsDb.Add(cmd,"id",NpgsqlDbType.Text,id);TestsDb.Add(cmd,"version",NpgsqlDbType.Text,version);await using var r=await cmd.ExecuteReaderAsync(CommandBehavior.SingleRow,ct);if(!await r.ReadAsync(ct))return null;var x=JsonSerializer.Deserialize<GovernedCiCdWorkflowDefinition>(r.GetString(0))??throw new InvalidOperationException();if(!StringComparer.OrdinalIgnoreCase.Equals(r.GetString(1),TestsDb.Digest(x))||!x.SignatureValid||!x.LeastPrivilege||!x.ImmutableTaskReferences)throw new InvalidOperationException("Workflow binding invalid.");return x;}catch(NpgsqlException){throw new CiCdDependencyUnavailableException("Workflow catalog unavailable.");}}}
public sealed class PostgreSqlCiCdEvidenceRecorder(NpgsqlDataSource data,IOptions<PostgreSqlIntentRegistrationOptions> cfg):ICiCdEvidenceRecorder{private const string SelectSql="SELECT delivery_run_id,manifest_sha256_digest,record_sha256_digest,evidence_reference,recorded_at FROM software_factory.cicd_evidence WHERE tenant_id=@tenant AND execution_id=@id FOR UPDATE";public async Task<CiCdEvidenceReceipt> RecordAsync(CiCdEvidenceRecord x,CancellationToken ct){var o=cfg.Value;if(!o.IsOperationallyConfigured)throw new CiCdDependencyUnavailableException("CI/CD evidence not configured.");var d=TestsDb.Digest(x);var ev=$"evidence://cicd/{x.ExecutionId:D}/sha256/{d}";try{await using var cn=await data.OpenConnectionAsync(ct);await using var tx=await cn.BeginTransactionAsync(IsolationLevel.Serializable,ct);var old=await Load(cn,tx,x.TenantId,x.ExecutionId,o.CommandTimeoutSeconds,ct);if(old is not null){Check(x,d,old);await tx.CommitAsync(ct);return old.Receipt;}const string sql="INSERT INTO software_factory.cicd_evidence(tenant_id,execution_id,git_operation_id,delivery_run_id,manifest_sha256_digest,record_sha256_digest,record_json,evidence_reference,evidence_references,recorded_at) VALUES(@tenant,@id,@git,@run,@manifest,@digest,@json,@evidence,@refs,@at) ON CONFLICT DO NOTHING";await using var cmd=new NpgsqlCommand(sql,cn,tx){CommandTimeout=o.CommandTimeoutSeconds};foreach(var p in new[]{("tenant",NpgsqlDbType.Text,(object)x.TenantId),("id",NpgsqlDbType.Uuid,x.ExecutionId),("git",NpgsqlDbType.Uuid,x.GitOperationId),("run",NpgsqlDbType.Uuid,x.DeliveryRunId),("manifest",NpgsqlDbType.Text,x.Result.OutputManifest.ManifestSha256Digest),("digest",NpgsqlDbType.Text,d),("json",NpgsqlDbType.Jsonb,JsonSerializer.Serialize(x)),("evidence",NpgsqlDbType.Text,ev),("refs",NpgsqlDbType.Array|NpgsqlDbType.Text,x.EvidenceReferences.ToArray()),("at",NpgsqlDbType.TimestampTz,x.AuthorizedAt)})TestsDb.Add(cmd,p.Item1,p.Item2,p.Item3);if(await cmd.ExecuteNonQueryAsync(ct)==0){old=await Load(cn,tx,x.TenantId,x.ExecutionId,o.CommandTimeoutSeconds,ct)??throw new InvalidOperationException("CI/CD evidence identity conflict.");Check(x,d,old);await tx.CommitAsync(ct);return old.Receipt;}await tx.CommitAsync(ct);return new(x.ExecutionId,x.DeliveryRunId,x.TenantId,x.Result.OutputManifest.ManifestSha256Digest,ev,x.AuthorizedAt);}catch(NpgsqlException){throw new CiCdDependencyUnavailableException("CI/CD evidence unavailable.");}}private static async Task<Stored?> Load(NpgsqlConnection cn,NpgsqlTransaction tx,string tenant,Guid id,int timeout,CancellationToken ct){await using var cmd=new NpgsqlCommand(SelectSql,cn,tx){CommandTimeout=timeout};TestsDb.Add(cmd,"tenant",NpgsqlDbType.Text,tenant);TestsDb.Add(cmd,"id",NpgsqlDbType.Uuid,id);await using var r=await cmd.ExecuteReaderAsync(CommandBehavior.SingleRow,ct);if(!await r.ReadAsync(ct))return null;return new(new(id,r.GetGuid(0),tenant,r.GetString(1),r.GetString(3),new(r.GetDateTime(4).ToUniversalTime())),r.GetString(2));}private static void Check(CiCdEvidenceRecord x,string d,Stored s){if(s.Receipt.DeliveryRunId!=x.DeliveryRunId||!StringComparer.OrdinalIgnoreCase.Equals(s.Receipt.ManifestSha256Digest,x.Result.OutputManifest.ManifestSha256Digest)||!StringComparer.OrdinalIgnoreCase.Equals(s.Digest,d))throw new InvalidOperationException("Stored CI/CD evidence mismatch.");}private sealed record Stored(CiCdEvidenceReceipt Receipt,string Digest);}
